package dev.hoi.client.screen;

import dev.hoi.protocol.*;
import java.nio.file.*;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.input.*;
import com.mojang.blaze3d.platform.InputConstants;

public final class ScreenDivisionDialogsTest {
    private ScreenDivisionDialogsTest() {}
    private static MouseButtonEvent click(AbstractWidget b,int button){return new MouseButtonEvent(b.getX()+b.getWidth()/2.,b.getY()+b.getHeight()/2.,new MouseButtonInfo(button,0));}
    public static void run(ClientGameTestContext game,ProtocolMenuView menu){
        int previous=game.computeOnClient(c->c.options.guiScale().get());
        try{
            var source=new ProtocolDialogPayloads.Show(Files.readString(Path.of(System.getenv("HOI_COMMANDER_PREVIEW"),"kor-disband-confirm.json")),true).view().issued(UUID.randomUUID().toString(),7);
            for(int[] size:List.of(new int[]{2560,1440},new int[]{1280,720})){
                game.getInput().resizeWindow(size[0],size[1]);game.runOnClient(c->{c.options.guiScale().set(2);dev.hoi.client.ClientCampaignHud.accept(ProtocolHudPayloads.State.of("KOR",menu.hud()));try{var card=new com.google.gson.Gson().fromJson(Files.readString(Path.of(System.getenv("HOI_COMMANDER_PREVIEW"),"kor-army-panel-tooltips.json")),ProtocolCommanderHud.Card.class);dev.hoi.client.map.MapCommanderHud.accept(new ProtocolCommanderHud.View("KOR",c.level.dimension().identifier().toString(),ProtocolCommanderHud.Mode.ARMY,List.of(card)));dev.hoi.client.map.MapArmyTooltipTest.selectCard(card.id());}catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}});
                var views=new LinkedHashMap<String,ProtocolDialogView>();views.put("disband-source",source);
                for(String name:List.of("kor-template-confirm","kor-template-list")){var p=Path.of(System.getenv("HOI_COMMANDER_PREVIEW"),name+".json");if(Files.exists(p))views.put(name,new ProtocolDialogPayloads.Show(Files.readString(p),true).view().issued(UUID.randomUUID().toString(),7));}
                if(!views.containsKey("kor-template-confirm"))views.put("template-confirm-synthetic",new ProtocolDialogView(UUID.randomUUID().toString(),7,source.kind(),dev.hoi.client.ui.UiCommandLabels.text("CONFIRMCHANGE_UNIT_TEMPLATE",""),"","필요:\n§Y1367§! 인력(409K 이용 가능)\n\n획득:\n§Y100§! 보병 장비","","","",List.of(),source.choices()));
                for(var entry:views.entrySet()){
                    if(ScreenDivisionTemplates.matches(entry.getValue()))continue;
                    var view=entry.getValue();game.runOnClient(c->{ScreenDialogCoordinator.reset();ScreenDialogCoordinator.receive(new ProtocolDialogPayloads.Show(new com.google.gson.Gson().toJson(view),true));if(!(c.gui.screen() instanceof ScreenCommanderConfirmation))throw new AssertionError("Division confirmation routing");});
                    for(String id:List.of("confirm","cancel")){
                        var sent=new ArrayList<String>();var screen=game.computeOnClient(c->new ScreenCommanderConfirmation(view,(v,choice)->sent.add(v.token()+"/"+v.revision()+"/"+choice)));game.setScreen(()->screen);game.getInput().setCursorPos(size[0]-5,80);game.waitTicks(3);game.runOnClient(c->dev.hoi.client.map.MapArmyTooltipTest.assertPanelBackdrop());game.takeScreenshot("hoi-"+entry.getKey()+"-"+id+"-"+size[0]+"-gui2");
                        game.runOnClient(c->{var b=screen.choiceButton(id);screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_RIGHT),false);if(!sent.isEmpty())throw new AssertionError("Right click confirmed");screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_LEFT),false);screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_LEFT),true);if(!sent.equals(List.of(view.token()+"/7/"+id)))throw new AssertionError("One issued action required");screen.update(view);if(screen.choiceButton(id).active)throw new AssertionError("Same revision unlocked");});
                    }
                }
                var longView=new ProtocolDialogView(UUID.randomUUID().toString(),7,source.kind(),source.title(),source.subtitle(),source.body()+"\n\n"+source.body().repeat(3),source.flag(),source.image(),source.sound(),source.tiles(),source.choices());var longScreen=game.computeOnClient(c->new ScreenCommanderConfirmation(longView,(v,id)->{}));game.setScreen(()->longScreen);game.waitTicks(2);game.runOnClient(c->longScreen.mouseScrolled(longScreen.width/2.,longScreen.height/2.,0,-100));game.waitTicks(2);game.takeScreenshot("hoi-disband-long-scrolled-synthetic-"+size[0]+"-gui2");
                var blocked=new ProtocolDialogView(UUID.randomUUID().toString(),7,source.kind(),source.title(),source.subtitle(),"§R전투 중인 사단은 해산할 수 없습니다.§!",source.flag(),source.image(),source.sound(),source.tiles(),source.choices().stream().filter(c->c.id().equals("cancel")).toList());var sent=new ArrayList<String>();var denied=game.computeOnClient(c->new ScreenCommanderConfirmation(blocked,(v,id)->sent.add(id)));game.setScreen(()->denied);game.waitTicks(2);game.takeScreenshot("hoi-disband-blocked-synthetic-"+size[0]+"-gui2");game.runOnClient(c->{if(denied.choiceButton("confirm")!=null)throw new AssertionError("Blocked confirm visible");denied.onClose();denied.onClose();if(!sent.equals(List.of("cancel")))throw new AssertionError("Cancel must be singular");});
                var tiles=new ArrayList<ProtocolDialogView.Tile>();var choices=new ArrayList<ProtocolDialogView.Choice>();for(int i=0;i<18;i++){String id="template/test-"+i;tiles.add(new ProtocolDialogView.Tile(id,"시험 편제 "+i,"","unit_hud/infantry",i==0?"특수부대 상한을 초과하게 되므로 이 편제로 변경할 수 없습니다.":"편제 시험 툴팁"));if(i>0)choices.add(new ProtocolDialogView.Choice(id,"시험 편제 "+i));}choices.add(new ProtocolDialogView.Choice("cancel","취소"));
                var list=views.getOrDefault("kor-template-list",new ProtocolDialogView(UUID.randomUUID().toString(),7,source.kind(),"사단 편제 변경","","","","","",tiles,choices));game.runOnClient(c->{ScreenDialogCoordinator.reset();var json=new com.google.gson.Gson();ScreenDialogCoordinator.receive(new ProtocolDialogPayloads.Show(json.toJson(list),true));if(!(c.gui.screen() instanceof ScreenDivisionTemplates))throw new AssertionError("Template routing");ScreenDialogCoordinator.receive(new ProtocolDialogPayloads.Show(json.toJson(source.issued(list.token(),list.revision())),true));if(!(c.gui.screen() instanceof ScreenDivisionTemplates))throw new AssertionError("Same revision replaced template");ScreenDialogCoordinator.receive(new ProtocolDialogPayloads.Show(json.toJson(source.issued(list.token(),list.revision()+1)),true));if(!(c.gui.screen() instanceof ScreenCommanderConfirmation))throw new AssertionError("New revision confirmation routing");ScreenDialogCoordinator.reset();});var actions=new ArrayList<String>();var screen=game.computeOnClient(c->new ScreenDivisionTemplates(list,(v,id)->actions.add(id)));game.setScreen(()->screen);game.getInput().setCursorPos(48,280);game.waitTicks(3);game.takeScreenshot("hoi-template-list-"+(views.containsKey("kor-template-list")?"source":"synthetic")+"-"+size[0]+"-gui2");
                var blockedTemplate=list.tiles().stream().filter(t->list.choices().stream().noneMatch(choice->choice.id().equals(t.section()))).findFirst().orElseThrow();
                game.runOnClient(c->{for(int step=0;step<list.tiles().size()&&screen.choiceButton(blockedTemplate.section())==null;step++)screen.mouseScrolled(40,140,0,-1);});
                var blockedButton=game.computeOnClient(c->screen.choiceButton(blockedTemplate.section()));game.getInput().setCursorPos((blockedButton.getX()+blockedButton.getWidth()/2.)*2,(blockedButton.getY()+4)*2);game.waitTicks(10);game.takeScreenshot("hoi-template-blocked-tooltip-"+size[0]+"-gui2");
                game.runOnClient(c->screen.mouseScrolled(40,140,0,100));
                game.runOnClient(c->{var first=list.tiles().getFirst();var b=screen.choiceButton(first.section());if(list.choices().stream().noneMatch(x->x.id().equals(first.section()))){if(b.active)throw new AssertionError("Unissued template active");screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_LEFT),false);if(!actions.isEmpty())throw new AssertionError("Disabled template sent");}screen.mouseScrolled(40,140,0,-100);});game.waitTicks(2);game.takeScreenshot("hoi-template-list-scrolled-"+size[0]+"-gui2");
                game.runOnClient(c->{if(list.tiles().size()>5){double x=121,y=dev.hoi.client.ui.UiMenuBar.height(screen.width)+110;var press=new MouseButtonEvent(x,y,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));if(!screen.mouseClicked(press,false))throw new AssertionError("Scrollbar press");screen.mouseDragged(new MouseButtonEvent(x,y+120,new MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0)),0,120);screen.mouseReleased(press);if(screen.choiceButton(list.tiles().getLast().section())==null)throw new AssertionError("Scrollbar drag must expose last row");}});
                game.runOnClient(c->{var b=screen.children().stream().filter(x->x instanceof AbstractWidget w&&w.active).map(x->(AbstractWidget)x).findFirst().orElseThrow();screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_LEFT),false);screen.mouseClicked(click(b,InputConstants.MOUSE_BUTTON_LEFT),true);if(actions.size()!=1)throw new AssertionError("Template choice must send once");screen.update(list);if(screen.children().stream().anyMatch(x->x instanceof AbstractWidget w&&w.active))throw new AssertionError("Same revision unlocked template");});
            }
        }catch(java.io.IOException e){throw new java.io.UncheckedIOException(e);}finally{game.runOnClient(c->{ScreenDialogCoordinator.reset();dev.hoi.client.map.MapCommanderHud.reset();c.options.guiScale().set(previous);});game.setScreen(()->null);}
    }
}
